45	                                                    bool clientNoContextTakeOver)
46	    {
47	#ifdef IXWEBSOCKET_USE_ZLIB
48	        int ret = deflateInit2(&_deflateState,
49	                               Z_DEFAULT_COMPRESSION,
50	                               Z_DEFLATED,
51	                               -1 * deflateBits,
52	                               4, // memory level 1-9
53	                               Z_DEFAULT_STRATEGY);
