68	    bool WebSocketPerMessageDeflateCompressor::endsWithEmptyUnCompressedBlock(const T& value)
69	    {
70	        if (kEmptyUncompressedBlock.size() > value.size()) return false;
71	        auto N = value.size();
72	        return value[N - 1] == kEmptyUncompressedBlock[3] &&
73	               value[N - 2] == kEmptyUncompressedBlock[2] &&
74	               value[N - 3] == kEmptyUncompressedBlock[1] &&
75	               value[N - 4] == kEmptyUncompressedBlock[0];
76	    }
