198	                                                      bool clientNoContextTakeOver)
199	    {
200	#ifdef IXWEBSOCKET_USE_ZLIB
201	        int ret = inflateInit2(&_inflateState, -1 * inflateBits);
202	
203	        if (ret != Z_OK) return false;
204	
205	        _flush = (clientNoContextTakeOver) ? Z_FULL_FLUSH : Z_SYNC_FLUSH;
206	
207	        return true;
208	#else
209	        (void) inflateBits;
210	        (void) clientNoContextTakeOver;
211	        return false;
212	#endif
213	    }
214	
215	    bool WebSocketPerMessageDeflateDecompressor::decompress(const std::string& in, std::string& out)
216	    {
217	#ifdef IXWEBSOCKET_USE_ZLIB
218	        //
219	        // 7.2.2.  Decompression
220	        //
221	        //    An endpoint uses the following algorithm to decompress a message.
222	        //
223	        //    1.  Append 4 octets of 0x00 0x00 0xff 0xff to the tail end of the
224	        //        payload of the message.
225	        //
226	        //    2.  Decompress the resulting data using DEFLATE.
227	        //
228	        std::string inFixed(in);
229	        inFixed += kEmptyUncompressedBlock;
230	
231	        _inflateState.avail_in = (uInt) inFixed.size();
232	        _inflateState.next_in = (unsigned char*) (const_cast<char*>(inFixed.data()));
233	
234	        // Clear output
235	        out.clear();
236	
237	        do
238	        {
239	            _inflateState.avail_out = (uInt) _compressBuffer.size();
240	            _inflateState.next_out = &_compressBuffer.front();
241	
242	            int ret = inflate(&_inflateState, Z_SYNC_FLUSH);
243	
244	            if (ret == Z_NEED_DICT || ret == Z_DATA_ERROR || ret == Z_MEM_ERROR)
245	            {
246	                return false; // zlib error
247	            }
248	
249	            out.append(reinterpret_cast<char*>(&_compressBuffer.front()),
250	                       _compressBuffer.size() - _inflateState.avail_out);
251	        } while (_inflateState.avail_out == 0);
252	
