233	    void WebSocketTransport::setReadyState(ReadyState readyState)
234	    {
235	        // Lock the _setReadyStateMutex for the duration of this
236	        // method. This ensures that only a single thread runs the
237	        // logic below avoiding concurrent execution of the
238	        // close callback my multiple threads at the same time.
239	        std::lock_guard<std::mutex> lock(_setReadyStateMutex);
240	
241	        // No state change, return
242	        if (_readyState == readyState) return;
243	
244	        if (readyState == ReadyState::CLOSED)
245	        {
246	            if (_onCloseCallback)
247	            {
248	                _onCloseCallback(_closeCode, getCloseReason(), _closeWireSize, _closeRemote);
249	            }
250	            setCloseReason(WebSocketCloseConstants::kInternalErrorMessage);
251	            _closeCode = WebSocketCloseConstants::kInternalErrorCode;
252	            _closeWireSize = 0;
253	            _closeRemote = false;
254	        }
255	        else if (readyState == ReadyState::OPEN)
256	        {
257	            initTimePointsAfterConnect();
258	            _pongReceived = false;
259	        }
260	
261	        _readyState = readyState;
262	    }
