277	    // Only consider send PING time points for that computation.
278	    bool WebSocketTransport::pingIntervalExceeded()
279	    {
280	        if (_pingIntervalSecs <= 0) return false;
281	
282	        std::lock_guard<std::mutex> lock(_lastSendPingTimePointMutex);
283	        auto now = std::chrono::steady_clock::now();
284	        return now - _lastSendPingTimePoint > std::chrono::seconds(_pingIntervalSecs);
