838	    void WebSocketTransport::emitMessage(MessageKind messageKind,
839	                                         const std::string& message,
840	                                         bool compressedMessage,
841	                                         const OnMessageCallback& onMessageCallback)
842	    {
843	        size_t wireSize = message.size();
844	
845	        // When the RSV1 bit is 1 it means the message is compressed
846	        if (compressedMessage && messageKind != MessageKind::FRAGMENT)
847	        {
848	            bool success = _perMessageDeflate->decompress(message, _decompressedMessage);
849	
850	            if (messageKind == MessageKind::MSG_TEXT && !validateUtf8(_decompressedMessage))
851	            {
852	                close(WebSocketCloseConstants::kInvalidFramePayloadData,
853	                      WebSocketCloseConstants::kInvalidFramePayloadDataMessage);
854	            }
855	            else
856	            {
857	                onMessageCallback(_decompressedMessage, wireSize, !success, messageKind);
858	            }
859	        }
860	        else
861	        {
862	            if (messageKind == MessageKind::MSG_TEXT && !validateUtf8(message))
863	            {
864	                close(WebSocketCloseConstants::kInvalidFramePayloadData,
865	                      WebSocketCloseConstants::kInvalidFramePayloadDataMessage);
866	            }
867	            else
868	            {
869	                onMessageCallback(message, wireSize, false, messageKind);
870	            }
871	        }
872	    }
