1116	    bool WebSocketTransport::sendOnSocket()
1117	    {
1118	        std::lock_guard<std::mutex> lock(_txbufMutex);
1119	
1120	        while (_txbuf.size())
1121	        {
1122	            std::ptrdiff_t ret = 0;
1123	            {
1124	                std::lock_guard<std::mutex> lock(_socketMutex);
1125	                ret = _socket->send((char*) &_txbuf[0], _txbuf.size());
1126	            }
1127	
1128	            if (ret < 0 && Socket::isWaitNeeded())
1129	            {
1130	                break;
1131	            }
1132	            else if (ret <= 0)
1133	            {
1134	                closeSocket();
1135	                if (_readyState != ReadyState::CLOSING)
1136	                {
1137	                    setReadyState(ReadyState::CLOSED);
1138	                }
1139	                return false;
1140	            }
1141	            else
1142	            {
1143	                _txbuf.erase(_txbuf.begin(), _txbuf.begin() + ret);
1144	            }
1145	        }
1146	
1147	        return true;
1148	    }
1149	
1150	    bool WebSocketTransport::receiveFromSocket()
1151	    {
1152	        while (true)
1153	        {
1154	            // If _rxbufWanted isn't set, don't attempt to read more than kChunkSize
1155	            // into _rxbuf. If a client is sending frames faster than they can be
1156	            // processed this would otherwise bloat _rxbuf and further introduce
1157	            // unnecessary processing overhead due to .erase() in dispatch().
1158	            //
1159	            // Further, not reading everything from the socket will eventually
1160	            // result in back pressure for the client.
1161	            if (_rxbufWanted == 0 && _rxbuf.size() >= kChunkSize) break;
1162	
1163	            // There's also no point in reading more bytes than needed.
1164	            if (_rxbufWanted > 0 && _rxbuf.size() >= _rxbufWanted) break;
1165	
1166	            std::ptrdiff_t ret = _socket->recv((char*) &_readbuf[0], _readbuf.size());
1167	
1168	            if (ret < 0 && Socket::isWaitNeeded())
1169	            {
1170	                break;
1171	            }
1172	            else if (ret <= 0)
1173	            {
1174	                // if there are received data pending to be processed, then delay the abnormal
1175	                // closure to after dispatch (other close code/reason could be read from the
1176	                // buffer)
1177	
1178	                closeSocket();
1179	                return false;
1180	            }
1181	            else
1182	            {
1183	                _rxbuf.insert(_rxbuf.end(), _readbuf.begin(), _readbuf.begin() + ret);
1184	            }
1185	        }
1186	
1187	        return true;
1188	    }
1189	
1190	    void WebSocketTransport::sendCloseFrame(uint16_t code, const std::string& reason)
1191	    {
1192	        bool compress = false;
1193	
1194	        // if a status is set/was read
1195	        if (code != WebSocketCloseConstants::kNoStatusCodeErrorCode)
1196	        {
1197	            // See list of close events here:
1198	            // https://developer.mozilla.org/en-US/docs/Web/API/CloseEvent
1199	            std::string closure {(char) (code >> 8), (char) (code & 0xff)};
1200	
1201	            // copy reason after code
1202	            closure.append(reason);
1203	
1204	            sendData(wsheader_type::CLOSE, closure, compress);
1205	        }
1206	        else
1207	        {
1208	            // no close code/reason set
1209	            sendData(wsheader_type::CLOSE, std::string(""), compress);
1210	        }
1211	    }
