1	/*
2	 * IXWebSocketDecompressionFailureTest.cpp
3	 *
4	 * Verifies that a message whose compressed payload is rejected by zlib fails
5	 * the whole message and tears down the connection, on both client and server
6	 * sides, for both text and binary messages. Also verifies that valid
7	 * compressed messages (empty, larger than 32KiB, fragmented, using context
8	 * takeover) keep being delivered correctly, and that a later reconnect on the
9	 * same WebSocket object starts from a clean state.
10	 */
11	
12	#include "IXTest.h"
13	#include "catch_amalgamated.hpp"
14	#include <atomic>
15	#include <chrono>
16	#include <cstring>
17	#include <functional>
18	#include <ixwebsocket/IXGetFreePort.h>
19	#include <ixwebsocket/IXWebSocket.h>
20	#include <ixwebsocket/IXWebSocketCloseConstants.h>
21	#include <ixwebsocket/IXWebSocketHandshakeKeyGen.h>
22	#include <ixwebsocket/IXWebSocketPerMessageDeflateCodec.h>
23	#include <ixwebsocket/IXWebSocketServer.h>
24	#include <list>
25	#include <mutex>
26	#include <netinet/in.h>
27	#include <netinet/tcp.h>
28	#include <string>
29	#include <sys/socket.h>
30	#include <thread>
31	#include <unistd.h>
32	#include <vector>
33	#include <zlib.h>
34	
35	using namespace ix;
36	
37	namespace
38	{
39	    //
40	    // A minimal raw WebSocket peer speaking permessage-deflate over TCP.
41	    //
42	    class RawPeer
43	    {
44	    public:
45	        ~RawPeer()
46	        {
47	            reset();
48	        }
49	
50	        // Listen so a websocket *client* can connect to this peer (peer acts as
51	        // a permessage-deflate server).
52	        bool listen()
53	        {
54	            _listenFd = ::socket(AF_INET, SOCK_STREAM, 0);
55	            REQUIRE(_listenFd >= 0);
56	            int yes = 1;
57	            setsockopt(_listenFd, SOL_SOCKET, SO_REUSEADDR, &yes, sizeof(yes));
58	
59	            sockaddr_in addr {};
60	            addr.sin_family = AF_INET;
61	            addr.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
62	            addr.sin_port = 0;
63	            REQUIRE(bind(_listenFd, (sockaddr*) &addr, sizeof(addr)) == 0);
64	            REQUIRE(::listen(_listenFd, 5) == 0);
65	
66	            socklen_t len = sizeof(addr);
67	            REQUIRE(getsockname(_listenFd, (sockaddr*) &addr, &len) == 0);
68	            _port = ntohs(addr.sin_port);
69	            return true;
70	        }
71	
72	        int port() const
73	        {
74	            return _port;
75	        }
76	
77	        // Block until one client has connected and finish the handshake (the
78	        // raw peer is the WebSocket server side of this exchange).
79	        bool acceptWithDeflate(const std::string& responseExtensions)
80	        {
81	            _fd = ::accept(_listenFd, nullptr, nullptr);
82	            REQUIRE(_fd >= 0);
83	            setNoDelay();
84	            return finishServerHandshake(responseExtensions);
85	        }
86	
87	        bool finishServerHandshake(const std::string& responseExtensions)
88	        {
89	            std::string request;
90	            char buf[1024];
91	            while (request.find("\r\n\r\n") == std::string::npos)
92	            {
93	                ssize_t n = ::recv(_fd, buf, sizeof(buf), 0);
94	                REQUIRE(n > 0);
95	                request.append(buf, (size_t) n);
96	            }
97	
98	            std::string key;
99	            const std::string keyHeader = "Sec-WebSocket-Key:";
100	            auto pos = request.find(keyHeader);
101	            REQUIRE(pos != std::string::npos);
102	            pos += keyHeader.size();
103	            while (pos < request.size() && (request[pos] == ' ' || request[pos] == '\t')) ++pos;
104	            auto end = request.find("\r\n", pos);
105	            key = request.substr(pos, end - pos);
106	
107	            char accept[29] = {};
108	            WebSocketHandshakeKeyGen::generate(key, accept);
109	
110	            std::string response = "HTTP/1.1 101 Switching Protocols\r\n"
111	                                   "Upgrade: websocket\r\n"
112	                                   "Connection: Upgrade\r\n"
113	                                   "Sec-WebSocket-Accept: " +
114	                                   std::string(accept) + "\r\n";
115	            if (!responseExtensions.empty())
116	            {
117	                response += "Sec-WebSocket-Extensions: " + responseExtensions + "\r\n";
118	            }
119	            response += "\r\n";
120	
121	            REQUIRE(sendAll(response));
122	            return true;
123	        }
124	
125	        // Connect this peer to a websocket *server* and perform the client
126	        // handshake requesting permessage-deflate.
127	        bool connect(int port)
128	        {
129	            _fd = ::socket(AF_INET, SOCK_STREAM, 0);
130	            REQUIRE(_fd >= 0);
131	            setNoDelay();
132	
133	            sockaddr_in addr {};
134	            addr.sin_family = AF_INET;
135	            addr.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
136	            addr.sin_port = htons((uint16_t) port);
137	            REQUIRE(::connect(_fd, (sockaddr*) &addr, sizeof(addr)) == 0);
138	
139	            std::string request =
140	                "GET / HTTP/1.1\r\n"
141	                "Host: localhost\r\n"
142	                "Upgrade: websocket\r\n"
143	                "Connection: Upgrade\r\n"
144	                "Sec-WebSocket-Key: dGhlIHNhbXBsZSBub25jZQ==\r\n"
145	                "Sec-WebSocket-Version: 13\r\n"
146	                "Sec-WebSocket-Extensions: permessage-deflate\r\n"
147	                "\r\n";
148	            REQUIRE(sendAll(request));
149	
150	            std::string response;
151	            char buf[1024];
152	            while (response.find("\r\n\r\n") == std::string::npos)
153	            {
154	                ssize_t n = ::recv(_fd, buf, sizeof(buf), 0);
155	                REQUIRE(n > 0);
156	                response.append(buf, (size_t) n);
157	            }
158	            REQUIRE(response.find("101") != std::string::npos);
159	            REQUIRE(response.find("permessage-deflate") != std::string::npos);
160	            return true;
161	        }
162	
163	        // Build a websocket frame.
164	        static std::string frame(int opcode,
165	                                 bool fin,
166	                                 bool rsv1,
167	                                 const std::string& payload,
168	                                 bool mask)
169	        {
170	            std::string out;
171	            uint8_t b0 = (uint8_t) opcode;
172	            if (fin) b0 |= 0x80;
173	            if (rsv1) b0 |= 0x40;
174	            out.push_back((char) b0);
175	
176	            uint8_t maskBit = mask ? 0x80 : 0;
177	            uint64_t n = payload.size();
178	            if (n < 126)
179	            {
180	                out.push_back((char) (maskBit | (uint8_t) n));
181	            }
182	            else if (n <= 0xffff)
183	            {
184	                out.push_back((char) (maskBit | 126));
185	                out.push_back((char) ((n >> 8) & 0xff));
186	                out.push_back((char) (n & 0xff));
187	            }
188	            else
189	            {
190	                out.push_back((char) (maskBit | 127));
191	                for (int i = 7; i >= 0; --i)
192	                {
193	                    out.push_back((char) ((n >> (8 * i)) & 0xff));
194	                }
195	            }
196	
197	            uint8_t key[4] = {0x12, 0x34, 0x56, 0x78};
198	            if (mask)
199	            {
200	                for (int i = 0; i < 4; ++i) out.push_back((char) key[i]);
201	            }
202	
203	            for (uint64_t i = 0; i < n; ++i)
204	            {
205	                char c = payload[i];
206	                if (mask) c ^= (char) key[i & 3];
207	                out.push_back(c);
208	            }
209	            return out;
210	        }
211	
212	        bool sendAll(const std::string& data)
213	        {
214	            size_t sent = 0;
215	            while (sent < data.size())
216	            {
217	                ssize_t n = ::send(_fd, data.data() + sent, data.size() - sent, 0);
218	                if (n <= 0) return false;
219	                sent += (size_t) n;
220	            }
221	            return true;
222	        }
223	
224	        bool sendFrame(int opcode,
225	                       bool fin,
226	                       bool rsv1,
227	                       const std::string& payload,
228	                       bool mask)
229	        {
230	            return sendAll(frame(opcode, fin, rsv1, payload, mask));
231	        }
232	
233	        // Send the given bytes one at a time, to exercise header/payload
234	        // reads that arrive in several socket reads.
235	        void sendByteByByte(const std::string& data)
236	        {
237	            for (char c : data)
238	            {
239	                REQUIRE(sendAll(std::string(1, c)));
240	                ix::msleep(1);
241	            }
242	        }
243	
244	        struct ParsedFrame
245	        {
246	            bool fin;
247	            bool rsv1;
248	            int opcode;
249	            std::string payload;
250	        };
251	
252	        // Read one frame (blocking). Returns false on clean/error close.
253	        bool recvFrame(ParsedFrame& frame)
254	        {
255	            uint8_t h[2];
256	            if (!recvExact(h, 2)) return false;
257	            frame.fin = (h[0] & 0x80) != 0;
258	            frame.rsv1 = (h[0] & 0x40) != 0;
259	            frame.opcode = h[0] & 0x0f;
260	            bool masked = (h[1] & 0x80) != 0;
261	            uint64_t n = h[1] & 0x7f;
262	            if (n == 126)
263	            {
264	                uint8_t e[2];
265	                if (!recvExact(e, 2)) return false;
266	                n = ((uint64_t) e[0] << 8) | e[1];
267	            }
268	            else if (n == 127)
269	            {
270	                uint8_t e[8];
271	                if (!recvExact(e, 8)) return false;
272	                n = 0;
273	                for (int i = 0; i < 8; ++i) n = (n << 8) | e[i];
274	            }
275	            uint8_t key[4] = {};
276	            if (masked)
277	            {
278	                if (!recvExact(key, 4)) return false;
279	            }
280	            frame.payload.resize((size_t) n);
281	            if (n > 0 && !recvExact((uint8_t*) &frame.payload[0], (size_t) n)) return false;
282	            if (masked)
283	            {
284	                for (uint64_t i = 0; i < n; ++i) frame.payload[i] ^= (char) key[i & 3];
285	            }
286	            return true;
287	        }
288	
289	        void closePeer()
290	        {
291	            if (_fd >= 0)
292	            {
293	                ::shutdown(_fd, SHUT_RDWR);
294	                ::close(_fd);
295	                _fd = -1;
296	            }
297	        }
298	
299	        void reset()
300	        {
301	            closePeer();
302	            if (_listenFd >= 0)
303	            {
304	                ::close(_listenFd);
305	                _listenFd = -1;
306	            }
307	        }
308	
309	        // Send back a CLOSE frame echoing code and reason.
310	        void sendCloseEcho(uint16_t code, const std::string& reason, bool mask)
311	        {
312	            std::string payload;
313	            payload.push_back((char) ((code >> 8) & 0xff));
314	            payload.push_back((char) (code & 0xff));
315	            payload += reason;
316	            sendFrame(8, true, false, payload, mask);
317	        }
318	
319	    private:
320	        void setNoDelay()
321	        {
322	            int yes = 1;
323	            setsockopt(_fd, IPPROTO_TCP, TCP_NODELAY, &yes, sizeof(yes));
324	        }
325	
326	        bool recvExact(uint8_t* dst, size_t n)
327	        {
328	            size_t got = 0;
329	            while (got < n)
330	            {
331	                ssize_t r = ::recv(_fd, dst + got, n - got, 0);
332	                if (r <= 0) return false;
333	                got += (size_t) r;
334	            }
335	            return true;
336	        }
337	
338	        int _listenFd = -1;
339	        int _fd = -1;
340	        int _port = 0;
341	    };
