343	    //
344	    // Raw DEFLATE compression with a reusable context (context takeover),
345	    // matching permessage-deflate without *_no_context_takeover.
346	    //
347	    class RawDeflater
348	    {
349	    public:
350	        RawDeflater()
351	        {
352	            memset(&_stream, 0, sizeof(_stream));
353	            REQUIRE(deflateInit2(&_stream,
354	                                Z_DEFAULT_COMPRESSION,
355	                                Z_DEFLATED,
356	                                -15,
357	                                4,
358	                                Z_DEFAULT_STRATEGY) == Z_OK);
359	        }
360	
361	        ~RawDeflater()
362	        {
363	            deflateEnd(&_stream);
364	        }
365	
366	        std::string compress(const std::string& in)
367	        {
368	            std::vector<uint8_t> out(in.size() + 64);
369	            _stream.avail_in = (uInt) in.size();
370	            _stream.next_in = (const_cast<uint8_t*>((const uint8_t*) in.data()));
371	            _stream.avail_out = (uInt) out.size();
372	            _stream.next_out = out.data();
373	            REQUIRE(deflate(&_stream, Z_SYNC_FLUSH) == Z_OK);
374	            size_t n = out.size() - _stream.avail_out;
375	            // strip the trailing 00 00 ff ff empty block marker
376	            REQUIRE(n >= 4);
377	            n -= 4;
378	            return std::string((char*) out.data(), n);
379	        }
380	
381	    private:
382	        z_stream _stream;
383	    };
384	
385	    struct Event
386	    {
387	        WebSocketMessageType type;
388	        std::string str;
389	        size_t wireSize = 0;
390	        bool binary = false;
391	        bool decompressionError = false;
392	        std::string reason;
393	        uint16_t closeCode = 0;
394	        std::string closeReason;
395	        bool closeRemote = false;
396	    };
397	
398	    struct EventLog
399	    {
400	        std::mutex mutex;
401	        std::list<Event> events;
402	        std::atomic<bool> sendInErrorCallbackFailed {false};
403	        std::atomic<bool> ready {false};
404	        WebSocket* ws = nullptr;
405	
406	        void push(const WebSocketMessagePtr& msg)
407	        {
408	            Event e;
409	            e.type = msg->type;
410	            e.str = msg->str;
411	            e.wireSize = msg->wireSize;
412	            e.binary = msg->binary;
413	            e.decompressionError = msg->errorInfo.decompressionError;
414	            e.reason = msg->errorInfo.reason;
415	            e.closeCode = msg->closeInfo.code;
416	            e.closeReason = msg->closeInfo.reason;
417	            e.closeRemote = msg->closeInfo.remote;
418	
419	            if (msg->type == WebSocketMessageType::Error &&
420	                msg->errorInfo.decompressionError && ws)
421	            {
422	                // Sending from within the error callback must fail: the
423	                // connection must already be closing.
424	                auto info = ws->send("should-fail", false);
425	                sendInErrorCallbackFailed = !info.success;
426	            }
427	
428	            std::lock_guard<std::mutex> lock(mutex);
429	            events.push_back(e);
430	            if (msg->type == WebSocketMessageType::Open) ready = true;
431	        }
432	
433	        std::vector<Event> snapshot()
434	        {
435	            std::lock_guard<std::mutex> lock(mutex);
436	            return std::vector<Event>(events.begin(), events.end());
437	        }
438	
439	        bool waitFor(WebSocketMessageType type, int timeoutMs = 5000)
440	        {
441	            auto deadline = std::chrono::steady_clock::now() +
442	                            std::chrono::milliseconds(timeoutMs);
443	            while (std::chrono::steady_clock::now() < deadline)
444	            {
445	                {
446	                    std::lock_guard<std::mutex> lock(mutex);
447	                    for (auto& e : events)
448	                        if (e.type == type) return true;
449	                }
450	                ix::msleep(10);
451	            }
452	            return false;
453	        }
454	
455	        bool waitForOpen(int timeoutMs = 5000)
456	        {
457	            auto deadline = std::chrono::steady_clock::now() +
458	                            std::chrono::milliseconds(timeoutMs);
459	            while (std::chrono::steady_clock::now() < deadline)
460	            {
461	                if (ready) return true;
462	                ix::msleep(10);
463	            }
464	            return false;
465	        }
466	    };
467	
468	    size_t countEvents(const std::vector<Event>& events, WebSocketMessageType type)
469	    {
470	        size_t n = 0;
471	        for (auto& e : events)
472	            if (e.type == type) ++n;
473	        return n;
474	    }
475	
476	    const Event* findEvent(const std::vector<Event>& events, WebSocketMessageType type)
477	    {
478	        for (auto& e : events)
479	            if (e.type == type) return &e;
480	        return nullptr;
481	    }
482	
483	    // Read frames coming from the websocket endpoint until its CLOSE frame is
484	    // seen; other frames (e.g. pong replies to pre-error pings) are recorded.
485	    std::vector<RawPeer::ParsedFrame> drainUntilClose(RawPeer& peer,
486	                                                      RawPeer::ParsedFrame& closeFrame)
487	    {
488	        std::vector<RawPeer::ParsedFrame> others;
489	        for (int i = 0; i < 100; ++i)
490	        {
491	            RawPeer::ParsedFrame f;
492	            if (!peer.recvFrame(f)) break;
493	            if (f.opcode == 8)
494	            {
495	                closeFrame = f;
496	                return others;
497	            }
498	            others.push_back(f);
499	        }
500	        FAIL("did not receive a CLOSE frame");
501	        return others;
502	    }
503	
504	    uint16_t closeCodeOf(const RawPeer::ParsedFrame& f)
505	    {
506	        REQUIRE(f.payload.size() >= 2);
507	        return ((uint16_t)(uint8_t) f.payload[0] << 8) | (uint8_t) f.payload[1];
508	    }
509	
510	    // Frame direction when the raw peer is the *server* talking to an ix client.
511	    const bool kServerToClientMasked = false;
512	    // Frame direction when the raw peer is the *client* talking to an ix server.
513	    const bool kClientToServerMasked = true;
514	
515	    // Verify common expectations after a decompression failure, regardless of
516	    // which side or which message type.
517	    void verifyFailureOutcome(EventLog& log,
518	                              size_t expectedWireSize,
519	                              const std::string& sentCloseReason)
520	    {
521	        REQUIRE(log.waitFor(WebSocketMessageType::Close, 5000));
522	        ix::msleep(200); // let any stray, forbidden events arrive
523	
524	        auto events = log.snapshot();
525	        auto error = findEvent(events, WebSocketMessageType::Error);
526	        REQUIRE(error != nullptr);
527	        REQUIRE(error->decompressionError == true);
528	        REQUIRE(error->str.empty());
529	        REQUIRE_FALSE(error->reason.empty());
530	        REQUIRE(error->wireSize == expectedWireSize);
531	
532	        REQUIRE(countEvents(events, WebSocketMessageType::Error) == 1);
533	        REQUIRE(countEvents(events, WebSocketMessageType::Close) == 1);
534	        // No data message, and no partial body, may be delivered for the
535	        // failed message.
536	        REQUIRE(findEvent(events, WebSocketMessageType::Message) == nullptr);
537	
538	        auto close = findEvent(events, WebSocketMessageType::Close);
539	        REQUIRE(close->closeCode == WebSocketCloseConstants::kInvalidFramePayloadData);
540	        REQUIRE(close->closeReason == sentCloseReason);
541	
542	        REQUIRE(log.sendInErrorCallbackFailed.load());
543	    }
