552	TEST_CASE("decompression_failure_client_single_byte", "[deflate][decompression]")
553	{
554	    // A single invalid compressed byte 0x07, both text and binary.
555	    for (int binary = 0; binary < 2; ++binary)
556	    {
557	        RawPeer peer;
558	        REQUIRE(peer.listen());
559	
560	        WebSocket ws;
561	        EventLog log;
562	        log.ws = &ws;
563	        ws.setUrl("ws://localhost:" + std::to_string(peer.port()) + "/");
564	        ws.disableAutomaticReconnection();
565	        ws.enablePerMessageDeflate();
566	        ws.setOnMessageCallback(
567	            [&log](const WebSocketMessagePtr& msg) { log.push(msg); });
568	        ws.start();
569	
570	        REQUIRE(peer.acceptWithDeflate("permessage-deflate"));
571	        REQUIRE(log.waitForOpen());
572	
573	        int opcode = binary ? 2 : 1;
574	        REQUIRE(peer.sendFrame(
575	            opcode, true, true, std::string(1, '\x07'), kServerToClientMasked));
576	
577	        REQUIRE(log.waitFor(WebSocketMessageType::Error));
578	
579	        // Frames following the bad one, even within later writes, must be
580	        // completely ignored: no delivery and no pong reply.
581	        REQUIRE(peer.sendFrame(
582	            1, true, false, "after-error", kServerToClientMasked));
583	        REQUIRE(peer.sendFrame(
584	            9, true, false, "ping-after", kServerToClientMasked));
