605	        auto events = log.snapshot();
606	        REQUIRE(countEvents(events, WebSocketMessageType::Fragment) == 0);
607	        REQUIRE(countEvents(events, WebSocketMessageType::Ping) == 0);
608	        REQUIRE(countEvents(events, WebSocketMessageType::Pong) == 0);
609	
610	        ws.stop();
611	    }
