828	        1, true, true, std::string("\x02\x00", 2), kServerToClientMasked));
829	
830	    // 2. Message larger than 32KiB, single (64-bit length) frame.
831	    std::string big(70 * 1024, 'z');
832	    REQUIRE(peer.sendFrame(
833	        1, true, true, deflater.compress(big), kServerToClientMasked));
834	
835	    // 3. Same large message split across multiple continuation frames.
836	    std::string compressed = deflater.compress(big);
837	    size_t half = compressed.size() / 2;
838	    REQUIRE(peer.sendFrame(
839	        2, false, true, compressed.substr(0, half), kServerToClientMasked));
840	    REQUIRE(peer.sendFrame(
841	        0, true, false, compressed.substr(half), kServerToClientMasked));
842	
843	    // 4. Consecutive compressed messages produced with context takeover.
844	    std::string a = "the quick brown fox jumps over the lazy dog";
845	    std::string b = "the quick brown fox jumps over the lazy dog (again)";
846	    REQUIRE(peer.sendFrame(
847	        1, true, true, deflater.compress(a), kServerToClientMasked));
848	    REQUIRE(peer.sendFrame(
849	        1, true, true, deflater.compress(b), kServerToClientMasked));
850	
851	    // Wait for all 5 messages (empty, big, big-binary-fragmented, a, b).
852	    bool delivered = false;
853	    for (int i = 0; i < 500; ++i)
854	    {
855	        auto ev = log.snapshot();
856	        if (countEvents(ev, WebSocketMessageType::Message) >= 5)
857	        {
858	            delivered = true;
859	            break;
860	        }
861	        ix::msleep(10);
862	    }
863	    REQUIRE(delivered);
864	
865	    auto events = log.snapshot();
866	    auto messages = std::vector<Event>();
867	    for (auto& e : events)
868	        if (e.type == WebSocketMessageType::Message) messages.push_back(e);
869	    REQUIRE(messages.size() == 5);
870	
871	    REQUIRE(messages[0].str == "");
872	    REQUIRE(messages[0].binary == false);
873	    REQUIRE(messages[1].str == big);
874	    REQUIRE(messages[1].binary == false);
875	    REQUIRE(messages[2].str == big);
876	    REQUIRE(messages[2].binary == true);
877	    REQUIRE(messages[3].str == a);
878	    REQUIRE(messages[4].str == b);
879	
880	    for (auto& e : events)
881	    {
882	        REQUIRE(e.type != WebSocketMessageType::Error);
883	        REQUIRE(e.type != WebSocketMessageType::Close);
884	    }
885	
886	    ws.stop();
887	}
888	
889	TEST_CASE("decompression_valid_before_error_client", "[deflate][decompression]")
890	{
891	    // A fully received valid message before the bad one is still delivered.
892	    RawDeflater deflater;
893	    std::string good = deflater.compress("perfectly valid message");
894	
895	    RawPeer peer;
896	    REQUIRE(peer.listen());
897	
898	    WebSocket ws;
899	    EventLog log;
900	    log.ws = &ws;
901	    ws.setUrl("ws://localhost:" + std::to_string(peer.port()) + "/");
902	    ws.disableAutomaticReconnection();
903	    ws.enablePerMessageDeflate();
904	    ws.setOnMessageCallback(
905	        [&log](const WebSocketMessagePtr& msg) { log.push(msg); });
906	    ws.start();
907	
908	    REQUIRE(peer.acceptWithDeflate("permessage-deflate"));
909	    REQUIRE(log.waitForOpen());
910	
911	    REQUIRE(peer.sendFrame(1, true, true, good, kServerToClientMasked));
912	
913	    // Wait for the good message to be delivered.
914	    bool gotGood = false;
915	    for (int i = 0; i < 200; ++i)
916	    {
917	        auto ev = log.snapshot();
918	        if (findEvent(ev, WebSocketMessageType::Message))
919	        {
920	            gotGood = true;
921	            break;
922	        }
923	        ix::msleep(10);
924	    }
925	    REQUIRE(gotGood);
926	
927	    REQUIRE(peer.sendFrame(
928	        1, true, true, std::string(1, '\x07'), kServerToClientMasked));
929	    REQUIRE(peer.sendFrame(
930	        1, true, true, good, kServerToClientMasked)); // must not be delivered
931	
932	    RawPeer::ParsedFrame closeFrame;
933	    drainUntilClose(peer, closeFrame);
934	    uint16_t code = closeCodeOf(closeFrame);
935	    std::string reason = closeFrame.payload.substr(2);
936	    peer.sendCloseEcho(code, reason, kServerToClientMasked);
937	
938	    REQUIRE(log.waitFor(WebSocketMessageType::Close));
939	    ix::msleep(200);
940	
941	    auto events = log.snapshot();
942	    REQUIRE(countEvents(events, WebSocketMessageType::Message) == 1);
943	    auto msg = findEvent(events, WebSocketMessageType::Message);
944	    REQUIRE(msg->str == "perfectly valid message");
945	    REQUIRE(countEvents(events, WebSocketMessageType::Error) == 1);
946	    REQUIRE(countEvents(events, WebSocketMessageType::Close) == 1);
947	
948	    ws.stop();
949	}
950	
951	// ---------------------------------------------------------------------------
952	// Server side: raw permessage-deflate client sends a bad compressed frame to
953	// an ix WebSocketServer.
954	// ---------------------------------------------------------------------------
955	
956	TEST_CASE("decompression_failure_server", "[deflate][decompression]")
957	{
958	    for (int binary = 0; binary < 2; ++binary)
959	    {
960	        int port = getFreePort();
961	        WebSocketServer server(port);
962	        EventLog log;
963	
964	        server.setOnClientMessageCallback(
965	            [&log, &server](std::shared_ptr<ConnectionState> state,
966	                            WebSocket& webSocket,
967	                            const WebSocketMessagePtr& msg) {
968	                (void) state;
969	                (void) server;
970	                log.ws = &webSocket;
971	                log.push(msg);
972	            });
973	
974	        auto res = server.listen();
975	        REQUIRE(res.first);
976	        server.start();
977	
978	        RawPeer peer;
979	        REQUIRE(peer.connect(port));
980	
981	        REQUIRE(log.waitForOpen());
982	
983	        int opcode = binary ? 2 : 1;
984	        REQUIRE(peer.sendFrame(
985	            opcode, true, true, std::string(1, '\x07'), kClientToServerMasked));
986	        // Post-error ping/message must be ignored by the server endpoint.
987	        REQUIRE(peer.sendFrame(
988	            9, true, false, "ping-after", kClientToServerMasked));
989	        REQUIRE(peer.sendFrame(
990	            1, true, false, "after-error", kClientToServerMasked));
991	
992	        REQUIRE(log.waitFor(WebSocketMessageType::Error));
993	
994	        RawPeer::ParsedFrame closeFrame;
995	        auto others = drainUntilClose(peer, closeFrame);
996	        uint16_t code = closeCodeOf(closeFrame);
997	        std::string reason = closeFrame.payload.substr(2);
998	        REQUIRE(code == WebSocketCloseConstants::kInvalidFramePayloadData);
999	        REQUIRE_FALSE(reason.empty());
1000	        for (auto& f : others)
1001	            REQUIRE(f.opcode != 0xa); // no pong for post-error ping
1002	
1003	        // The raw client echoes the close to finish the handshake.
1004	        peer.sendCloseEcho(code, reason, kClientToServerMasked);
1005	
1006	        verifyFailureOutcome(log, 1, reason);
1007	
1008	        auto events = log.snapshot();
1009	        REQUIRE(findEvent(events, WebSocketMessageType::Message) == nullptr);
1010	        REQUIRE(countEvents(events, WebSocketMessageType::Ping) == 0);
1011	
1012	        ix::msleep(200);
1013	        server.stop();
1014	    }
1015	}
1016	
1017	// ---------------------------------------------------------------------------
1018	// A failure only affects the current connection: reconnecting the same client
1019	// WebSocket object works and carries no leftover state.
1020	// ---------------------------------------------------------------------------
1021	
1022	TEST_CASE("decompression_failure_then_reconnect_client", "[deflate][decompression]")
1023	{
1024	    RawPeer peer;
1025	    REQUIRE(peer.listen());
1026	
1027	    WebSocket ws;
1028	    EventLog log;
1029	    log.ws = &ws;
1030	    ws.setUrl("ws://localhost:" + std::to_string(peer.port()) + "/");
1031	    ws.enablePerMessageDeflate(); // automatic reconnection stays enabled
1032	    ws.setOnMessageCallback(
1033	        [&log](const WebSocketMessagePtr& msg) { log.push(msg); });
1034	    ws.start();
1035	
