1037	    REQUIRE(peer.acceptWithDeflate("permessage-deflate"));
1038	    REQUIRE(log.waitForOpen());
1039	    REQUIRE(peer.sendFrame(
1040	        1, true, true, std::string(1, '\x07'), kServerToClientMasked));
1041	
