        if (messageKind == MessageKind::MSG_TEXT && !validateUtf8(_decompressedMessage))
        {
            close(WebSocketCloseConstants::kInvalidFramePayloadData,
                  WebSocketCloseConstants::kInvalidFramePayloadDataMessage);
        }
        else
