#include <ixwebsocket/IXWebSocketPerMessageDeflateCodec.h>
#include <cassert>
#include <iostream>
using namespace ix;
int main()
{
    // Build a payload: valid deflate stream of 40000 bytes, then an invalid block 0x07
    WebSocketPerMessageDeflateCompressor comp;
    comp.init(15, false);
    std::string big(40000, 'x'), compressed;
    comp.compress(big, compressed);
    std::string bad = compressed + std::string(1, '\x07');

    WebSocketPerMessageDeflateDecompressor decomp;
    decomp.init(15, false);
    std::string out("sentinel");
    bool ok = decomp.decompress(bad, out);
    std::cout << "ok=" << ok << " out.size()=" << out.size() << "\n";
    assert(!ok);
    assert(out.empty());

    // payload that is only 0x07
    out = "sentinel";
    ok = decomp.decompress(std::string(1, '\x07'), out);
    std::cout << "ok=" << ok << " out.size()=" << out.size() << "\n";
    assert(!ok && out.empty());

    // sanity: valid stream still decodes, exactly 16384 bytes too
    WebSocketPerMessageDeflateDecompressor d2;
    d2.init(15, false);
    ok = d2.decompress(compressed, out);
    assert(ok && out == big);
    WebSocketPerMessageDeflateCompressor c2;
    c2.init(15, false);
    std::string m(16384, 'y'), c3;
    c2.compress(m, c3);
    WebSocketPerMessageDeflateDecompressor d3;
    d3.init(15, false);
    ok = d3.decompress(c3, out);
    assert(ok && out == m);
    std::cout << "all codec checks passed\n";
    return 0;
}
EOF
